{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "A coumarin-containing analogue (Z18483535) has human oral bioavailability of 55.7%, directly supporting that coumarin-based scaffolds can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Felbamate, the highest-transfer analogue, has >90% oral bioavailability in humans, supporting high F for small aromatic drugs despite low structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Phenylbutyrate, a small lipophilic aromatic compound, has 78% oral bioavailability in patients, supporting high F for this class of small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Terodiline, a lipophilic aromatic drug, has a mean absolute oral bioavailability of 92% in healthy volunteers, supporting high F for lipophilic small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Baicalein, a polyhydroxylated flavone, has low oral bioavailability in humans, but its poor permeability and extensive conjugation are not shared by the 4-hydroxycoumarin query, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is phenprocoumon, a 4-hydroxycoumarin anticoagulant. Multiple transferable experimental analogues have oral bioavailability values above 20%, including a coumarin-containing compound at 55.7%, phenylbutyrate at 78%, terodiline at 92%, and felbamate at >90%. The only low-F analogue, baicalein, is a polyhydroxylated flavone with distinct permeability and conjugation liabilities. Therefore, high oral bioavailability (F >= 20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental F value for the exact query molecule in the supplied evidence set.",
    "All Morgan similarities are below 0.30, limiting quantitative transferability.",
    "The query's acidic ionization (pKa 4.53) is not directly probed by the high-F analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

